    @Override protected void onResume(){super.onResume();foreground=true;}
    @Override protected void onPause(){foreground=false;super.onPause();if(state!=null)persist();}
    @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
    private final Runnable tick=new Runnable(){public void run(){if(foreground&&state!=null&&state.active!=null&&page.equals("quiz")){StudyState.Session s=state.active;if(s.timed){s.remainingSeconds=Math.max(0,s.remainingSeconds-1);if(s.remainingSeconds%5==0)persist();if(s.remainingSeconds==0){toast("時間到，已自動交卷。");complete();}else if(timer!=null)timer.setText("剩餘 "+clock(s.remainingSeconds*1000L));}}handler.postDelayed(this,1000);}};
    private int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);}
    private String clock(long ms){long seconds=Math.max(0,ms/1000);return String.format(Locale.TAIWAN,"%02d:%02d",seconds/60,seconds%60);}
    private String date(long time){return new SimpleDateFormat("MM/dd HH:mm",Locale.TAIWAN).format(new Date(time));}
    private String bankDate(){try{java.time.format.DateTimeFormatter f=java.time.format.DateTimeFormatter.ofPattern("yyyy/MM/dd HH:mm").withZone(java.time.ZoneId.of("Asia/Taipei"));return f.format(java.time.Instant.parse(bank.date));}catch(Exception e){return bank.date;}}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
    private void persist(){try{state.save();}catch(Exception e){toast("紀錄暫時無法儲存，請檢查手機空間。");}}
    private void safely(Action action){try{action.run();}catch(Exception e){new AlertDialog.Builder(this).setTitle("請確認").setMessage(e.getMessage()==null?"操作無法完成，請重試。":e.getMessage()).setPositiveButton("知道了",null).show();}}
    private GradientDrawable shape(int color,int border){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(18));if(border!=0)d.setStroke(dp(1),border);return d;}
    private TextView text(String value,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setLineSpacing(dp(3),1);if(bold)t.setTypeface(null,Typeface.BOLD);return t;}
    private void gap(LinearLayout parent,int height){View v=new View(this);parent.addView(v,new LinearLayout.LayoutParams(1,dp(height)));}
    private TextView label(LinearLayout parent,String value,int size,int color,boolean bold){TextView t=text(value,size,color,bold);parent.addView(t,new LinearLayout.LayoutParams(-1,-2));return t;}
    private LinearLayout row(LinearLayout parent){LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.HORIZONTAL);r.setGravity(Gravity.CENTER_VERTICAL);parent.addView(r,new LinearLayout.LayoutParams(-1,-2));return r;}
    private LinearLayout card(LinearLayout parent,int color){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(shape(color,color==surface?line:0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);parent.addView(c,p);return c;}
    private Button button(LinearLayout parent,String caption,boolean primary,Action action){Button b=new Button(this);b.setText(caption);b.setAllCaps(false);b.setTextSize(16);b.setTextColor(primary?Color.rgb(24,31,33):ink);b.setTypeface(null,Typeface.BOLD);b.setBackground(shape(primary?yellow:surface,primary?0:line));b.setPadding(dp(12),dp(10),dp(12),dp(10));b.setMinHeight(dp(52));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(8);if(parent.getOrientation()==LinearLayout.HORIZONTAL){p.width=0;p.weight=1;p.leftMargin=dp(3);p.rightMargin=dp(3);}parent.addView(b,p);b.setOnClickListener(v->safely(action));return b;}
    private void palette(){boolean night=state.data.optBoolean("night");ink=Color.parseColor(night?"#F1F3F4":"#172022");muted=Color.parseColor(night?"#B0B8BD":"#667077");bg=Color.parseColor(night?"#111719":"#F6F7F5");surface=Color.parseColor(night?"#20292D":"#FFFFFF");line=Color.parseColor(night?"#344045":"#E0E5E3");}
    private void buildShell(){palette();root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(bg);area=new FrameLayout(this);root.addView(area,new LinearLayout.LayoutParams(-1,0,1));nav=new LinearLayout(this);nav.setPadding(dp(8),dp(6),dp(8),dp(8));nav.setBackgroundColor(surface);root.addView(nav,new LinearLayout.LayoutParams(-1,-2));setContentView(root);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(surface);getWindow().getDecorView().setSystemUiVisibility(state.data.optBoolean("night")?0:View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});root.requestApplyInsets();}
    private void screen(String name,String title,String subtitle){page=name;timer=null;area.removeAllViews();scroll=new ScrollView(this);scroll.setFillViewport(true);area.addView(scroll,new FrameLayout.LayoutParams(-1,-1));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(20),dp(22),dp(20),dp(24));scroll.addView(content,new ScrollView.LayoutParams(-1,-2));label(content,title,27,ink,true);if(!subtitle.isEmpty()){gap(content,3);label(content,subtitle,13,muted,false);}gap(content,20);nav.removeAllViews();nav.setVisibility(name.equals("quiz")?View.GONE:View.VISIBLE);String[] labels={"首頁","題庫","車庫","我的"};String[] names={"home","bank","garage","me"};for(int i=0;i<labels.length;i++){final int index=i;Button b=button(nav,labels[i],names[i].equals(name),()->{if(index==0)home();else if(index==1){bankMode="all";bankPage=0;bank();}else if(index==2)garage();else me();});b.setTextSize(14);b.setMinHeight(dp(48));}}
    private void home(){screen("home","計程車考照","把每一次練習，變成上路的底氣。");LinearLayout hero=card(content,yellow);label(hero,"準備好，下一站出發。",24,Color.rgb(24,31,33),true);gap(hero,8);label(hero,"離線題庫・原生測驗・隨時接著練",14,Color.rgb(52,57,53),false);hero.addView(new TaxiView(this,false),new LinearLayout.LayoutParams(-1,dp(124)));LinearLayout stats=row(content);stat(stats,"已掌握",String.valueOf(state.earned.size()),"題");stat(stats,"待複習",String.valueOf(currentWrong().size()),"題");stat(stats,"金幣",String.valueOf(state.data.optInt("coins")),"枚");gap(content,16);
        if(state.active!=null){LinearLayout c=card(content,surface);label(c,"上次還沒完成",15,muted,false);label(c,state.active.title+" · "+(state.active.index+1)+" / "+state.active.questions.size(),18,ink,true);button(c,"繼續作答",true,()->quiz());}
        button(content,"開始模擬考",true,()->setup(true));button(content,"自由練習",false,()->setup(false));LinearLayout quick=row(content);button(quick,"錯題複習",false,()->{bankMode="wrong";bankCity="全部地區";bankType=0;bankTopic="all";search="";bankPage=0;bank();});button(quick,"每日 5 題挑戰",false,()->challenge());gap(content,22);
        LinearLayout source=card(content,surface);label(source,"手機內已有 "+bank.questions.size()+" 題",17,ink,true);gap(source,5);label(source,"題庫內容更新："+bankDate()+"\n來源：警政署",12,muted,false);gap(source,8);label(source,updating?"正在檢查官方題庫…":state.data.optBoolean("lastCheckSucceeded",false)?"已更新到官方最新題庫":"已備妥離線題庫",15,green,true);button(source,updating?"正在檢查題庫…":"檢查題庫更新",false,()->updateBank(true));label(source,"每次開啟 App 自動檢查並更新，離線也能作答。",12,muted,false);
        label(content,"獨立開發的練習工具，非政府官方 App。",11,muted,false);
    }
    private void stat(LinearLayout parent,String title,String value,String unit){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(3),dp(13),dp(3),dp(13));box.setBackground(shape(surface,line));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),0,dp(3),0);parent.addView(box,p);TextView top=label(box,value,24,ink,true);top.setGravity(Gravity.CENTER);TextView bottom=label(box,title+" / "+unit,11,muted,false);bottom.setGravity(Gravity.CENTER);}
    private Spinner spinner(LinearLayout parent,String[] items,int selected){Spinner s=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,items){@Override public View getView(int position,View convert,ViewGroup parent){View v=super.getView(position,convert,parent);if(v instanceof TextView){((TextView)v).setTextColor(ink);((TextView)v).setText(items[position]+"  ▾");}return v;}@Override public View getDropDownView(int position,View convert,ViewGroup parent){View v=super.getDropDownView(position,convert,parent);v.setBackgroundColor(surface);if(v instanceof TextView)((TextView)v).setTextColor(ink);return v;}};adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);s.setAdapter(adapter);s.setSelection(Math.max(0,selected));s.setBackground(shape(surface,line));s.setPadding(dp(8),dp(8),dp(8),dp(8));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.topMargin=dp(7);p.bottomMargin=dp(12);parent.addView(s,p);return s;}
    private EditText numeric(LinearLayout parent,String caption,String value){label(parent,caption,14,ink,true);EditText e=new EditText(this);e.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);e.setSingleLine(true);e.setSelectAllOnFocus(true);e.setContentDescription(caption);e.setText(value);e.setTextSize(18);e.setTextColor(ink);e.setPadding(dp(16),dp(8),dp(16),dp(8));e.setBackground(shape(surface,line));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(52));p.topMargin=dp(6);p.bottomMargin=dp(16);parent.addView(e,p);return e;}
    private void watch(EditText e,Runnable action){e.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){action.run();}public void afterTextChanged(Editable e){}});}
    private int countValue(EditText e){try{return Math.max(0,Integer.parseInt(e.getText().toString()));}catch(Exception x){return 0;}}
    private void setup(boolean exam){
        screen("setup","建立一份模擬考卷","預設是非題 20 題、選擇題 30 題。可自行調整題數。" );
        label(content,"科目",14,ink,true);Spinner subject=spinner(content,new String[]{"地理環境","交通法規"},0);
        LinearLayout geography=new LinearLayout(this);geography.setOrientation(LinearLayout.VERTICAL);content.addView(geography);
        label(geography,"你報考哪一個縣市？",17,ink,true);label(geography,"選擇後會自動設定考區與出題比例。",13,muted,false);
        String[] cities=new String[ExamProfiles.REGISTRATION_REGIONS.length+1];cities[0]="請選擇報考縣市";System.arraycopy(ExamProfiles.REGISTRATION_REGIONS,0,cities,1,cities.length-1);
        Spinner city=spinner(geography,cities,Arrays.asList(cities).indexOf(state.data.optString("city","")));city.setContentDescription("報考縣市");
        TextView ratioSummary=label(geography,"選好報考縣市後，這裡會顯示考試範圍與比例。",16,green,true),note=label(geography,"",13,muted,false);
        Map<String,Integer> ratios=new LinkedHashMap<>();Map<String,EditText> inputs=new LinkedHashMap<>();boolean[] changing={false};
        LinearLayout quick=row(geography);Button only=button(quick,"只練報考縣市 100%",false,()->{}),restore=button(quick,"恢復考區比例",false,()->{});
        LinearLayout advanced=new LinearLayout(this);advanced.setOrientation(LinearLayout.VERTICAL);
        button(geography,"進階：自行調整比例",false,()->advanced.setVisibility(advanced.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));geography.addView(advanced);advanced.setVisibility(View.GONE);
        label(advanced,"只有大於 0% 的縣市會出題，合計需為 100%。",13,muted,false);
        for(String region:ExamProfiles.REGIONS)inputs.put(region,numeric(advanced,region+" 比例（%）","0"));
        TextView total=label(advanced,"比例合計 0%",17,green,true);gap(content,16);
        EditText tf=numeric(content,"是非題數（可以填 0）","20"),mc=numeric(content,"選擇題數（可以填 0）","30");
        TextView available=label(content,"",13,muted,false),timing=label(content,"",14,green,true);gap(content,10);
        Button start=button(content,"請先選擇報考縣市",true,()->{});
        Runnable refresh=()->{int sum=0;List<String> labels=new ArrayList<>();for(String r:ExamProfiles.REGIONS){int n=ratios.getOrDefault(r,0);sum+=n;if(n>0)labels.add(r+" "+n+"%");}ratioSummary.setText(labels.isEmpty()?"選好報考縣市後，這裡會顯示考試範圍與比例。":String.join("　",labels));total.setText("比例合計 "+sum+"%");total.setTextColor(sum==100?green:red);boolean law=subject.getSelectedItemPosition()==1;geography.setVisibility(law?View.GONE:View.VISIBLE);available.setText(law?"交通法規為全國共用題庫，不必選縣市。\n":"");available.append("目前可用：是非題 "+QuizCore.available(bank.questions,ratios,law,true)+" 題、選擇題 "+QuizCore.available(bank.questions,ratios,law,false)+" 題");timing.setText(countValue(tf)==20&&countValue(mc)==30?"正式模擬：是非 20 題＋選擇 30 題，限時 60 分鐘。":"自訂題數：不限時間，不會自動交卷。");start.setEnabled(law||sum==100);start.setText(!law&&sum==0?"請先選擇報考縣市":"開始作答");only.setEnabled(city.getSelectedItemPosition()>0);restore.setEnabled(city.getSelectedItemPosition()>0);};
        Runnable syncInputs=()->{changing[0]=true;for(String r:inputs.keySet())inputs.get(r).setText(String.valueOf(ratios.getOrDefault(r,0)));changing[0]=false;refresh.run();};
        for(Map.Entry<String,EditText> entry:inputs.entrySet())watch(entry.getValue(),()->{if(changing[0])return;int value=Math.min(100,countValue(entry.getValue()));ratios.put(entry.getKey(),value);if(countValue(entry.getValue())>100){changing[0]=true;entry.getValue().setText("100");changing[0]=false;}note.setText("目前使用你調整後的比例。");refresh.run();});
        Runnable applyProfile=()->{if(city.getSelectedItemPosition()==0){ratios.clear();note.setText("");}else{String selected=(String)city.getSelectedItem();ratios.clear();ratios.putAll(ExamProfiles.ratios(selected));JSONObject profile=guide.data.optJSONObject("profiles").optJSONObject(selected);note.setText(profile.optString("basis")+"："+profile.optString("note"));}syncInputs.run();};
        city.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){applyProfile.run();}});
        subject.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){refresh.run();}});
        only.setOnClickListener(v->{ratios.clear();ratios.put((String)city.getSelectedItem(),100);note.setText("目前使用你調整後的比例。");syncInputs.run();});restore.setOnClickListener(v->applyProfile.run());
        watch(tf,refresh);watch(mc,refresh);
        start.setOnClickListener(v->safely(()->{boolean law=subject.getSelectedItemPosition()==1;int nt=parseNumber(tf),nm=parseNumber(mc);int at=QuizCore.available(bank.questions,ratios,law,true),am=QuizCore.available(bank.questions,ratios,law,false);if(nt>at||nm>am){tf.setText(String.valueOf(Math.min(nt,at)));mc.setText(String.valueOf(Math.min(nm,am)));throw new Exception("已將題數調整為目前可用題數，請確認後開始。");}List<QuizCore.Question> selected=QuizCore.select(bank.questions,ratios,law,nt,nm,new Random());String region=city.getSelectedItemPosition()>0?(String)city.getSelectedItem():state.data.optString("city","基隆市");int limit=QuizCore.timeLimitSeconds(false,nt,nm);startSession(selected,true,limit/60,(law?"交通法規":region+" · 地理環境")+"測驗",region);}));
        applyProfile.run();button(content,"返回首頁",false,()->home());
    }
    private int parseNumber(EditText e)throws Exception {try{return Integer.parseInt(e.getText().toString().trim());}catch(Exception x){throw new Exception("題數與時間請填入整數。");}}
    private void startSession(List<QuizCore.Question> questions,boolean exam,int minutes,String title,String city){Action go=()->{state.active=new StudyState.Session(questions,exam,minutes,title);state.data.put("city",city);state.save();quiz();};if(state.active!=null)new AlertDialog.Builder(this).setTitle("開始新的練習？").setMessage("目前未交卷的練習會被這次取代；已完成的成績與錯題仍會保留。").setNegativeButton("繼續原練習",(d,w)->quiz()).setPositiveButton("開始新的",(d,w)->safely(go)).show();else safely(go);}
    private void challenge(){List<QuizCore.Question> list=new ArrayList<>();String city=state.data.optString("city","基隆市");for(QuizCore.Question q:bank.questions)if(q.city.equals(city)||q.city.equals("交通法規"))list.add(q);String day=new SimpleDateFormat("yyyyMMdd",Locale.ROOT).format(new Date());Collections.shuffle(list,new Random((day+city).hashCode()));startSession(list.subList(0,Math.min(5,list.size())),false,0,"每日 5 題挑戰",city);}
    private Set<String> currentWrong(){Set<String> ids=new HashSet<>(state.wrong);ids.retainAll(bank.byId.keySet());return ids;}
    private void updateBank(boolean manual){if(updating){if(manual)toast("題庫更新正在進行中。");return;}updating=true;if(manual)toast("正在比對題庫版本，舊題庫仍可使用。");final BankStore.Bank existing=bank;new Thread(()->{try{BankStore.Bank next=store.update(existing);runOnUiThread(()->{if(isDestroyed())return;bank=next;guide.setBank(next.questions);updating=false;safely(()->{state.data.put("lastCheck",System.currentTimeMillis()).put("lastCheckSucceeded",true);state.save();});if(manual||!existing.date.equals(next.date))toast(existing.date.equals(next.date)?"已更新到官方最新題庫":"題庫內容已更新，共 "+next.questions.size()+" 題。已更新到官方最新題庫");if(page.equals("home"))home();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;updating=false;safely(()->{state.data.put("lastCheckSucceeded",false);state.save();});if(page.equals("home"))home();if(manual)toast("更新未完成："+e.getMessage()+"\n繼續使用已下載的題庫。");});}},"update-bank").start();}
    private void quiz(){if(state.active==null){home();return;}StudyState.Session s=state.active;if(s.timed&&s.remainingSeconds<=0){complete();return;}screen("quiz",s.title,"第 "+(s.index+1)+" 題，共 "+s.questions.size()+" 題");timer=label(content,s.timed?"剩餘 "+clock(s.remainingSeconds*1000L):"自訂題數 · 不限時",15,s.exam?green:muted,true);int done=0;for(int a:s.answers)if(a>=0)done++;ProgressBar progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(s.questions.size());progress.setProgress(done);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(green));LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(8));pp.topMargin=dp(10);pp.bottomMargin=dp(18);content.addView(progress,pp);
        QuizCore.Question q=s.questions.get(s.index);LinearLayout c=card(content,surface);label(c,q.label(),13,muted,false);gap(c,12);label(c,q.stem,state.data.optInt("font",21),ink,true);gap(c,16);for(int n=0;n<q.choices;n++){final int choice=n;boolean picked=s.answers[s.index]==n;Button answer=button(c,q.optionLabel(n),picked,()->{int y=scroll.getScrollY();if(!s.exam&&s.answers[s.index]>=0)return;s.answers[s.index]=choice;state.save();quiz();scroll.post(()->scroll.scrollTo(0,y));});if(!s.exam&&s.answers[s.index]>=0){answer.setEnabled(false);if(n==q.answer){answer.setBackground(shape(green,0));answer.setTextColor(Color.WHITE);}else if(picked){answer.setBackground(shape(red,0));answer.setTextColor(Color.WHITE);}}}
        if(!s.exam&&s.answers[s.index]>=0){gap(c,12);boolean correct=s.answers[s.index]==q.answer;label(c,correct?"答對了！":"再記一次：正確答案是 "+q.answerLabel(),17,correct?green:red,true);}
        LinearLayout controls=row(content);int previous=QuizCore.nextUnanswered(s.answers,s.index,-1),next=QuizCore.nextUnanswered(s.answers,s.index);Button prev=button(controls,"上一題",false,()->{s.index=previous;state.save();quiz();});prev.setEnabled(previous>=0);
        int blanks=s.questions.size()-done;Button nextButton=button(controls,blanks==0?"交卷看成績":next<0?"請先完成本題":"下一題",true,()->{if(blanks==0){complete();return;}if(next>=0){s.index=next;state.save();quiz();}});nextButton.setEnabled(blanks==0||next>=0);
        button(content,"題號總覽 · 已答 "+done+" / "+s.questions.size(),false,()->questionGrid());label(content,"切題會略過已作答題目；要查看或修改答案，請使用題號總覽。",12,muted,false);
        button(content,"交卷並查看成績",false,()->askFinish());button(content,"儲存並返回首頁",false,()->{state.save();home();});if(s.timed)label(content,"儲存離開後保留剩餘時間，下次接著作答。",12,muted,false);
    }
    private void questionGrid(){StudyState.Session s=state.active;ScrollView sc=new ScrollView(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(dp(12),dp(12),dp(12),dp(12));sc.addView(panel);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("選擇題號（黃色表示已作答）").setView(sc).setNegativeButton("關閉",null).create();LinearLayout r=null;for(int i=0;i<s.questions.size();i++){if(i%5==0)r=row(panel);final int index=i;Button b=button(r,String.valueOf(i+1),s.answers[i]>=0,()->{s.index=index;state.save();dialog.dismiss();quiz();});b.setTextSize(13);b.setPadding(0,dp(8),0,dp(8));}dialog.show();}
    private void askFinish(){if(state.active==null)return;int blank=0;for(int a:state.active.answers)if(a<0)blank++;new AlertDialog.Builder(this).setTitle("交卷？").setMessage(blank>0?"還有 "+blank+" 題未作答，交卷後會列為未答與待複習。":"所有題目都已作答，現在查看成績。").setNegativeButton("繼續作答",null).setPositiveButton("交卷",(d,w)->complete()).show();}
    private void complete(){if(state.active==null)return;safely(()->{lastFinished=state.active;JSONObject result=state.finish();result(result);});}
    private void result(JSONObject r){screen("result","練習完成","每一題的累積，都算數。");LinearLayout c=card(content,yellow);label(c,r.optInt("score")>=70?"達到 70 分及格標準":"再複習一下就會更穩",16,Color.rgb(24,31,33),true);label(c,r.optInt("score")+" 分",48,Color.rgb(24,31,33),true);label(c,"答對 "+r.optInt("correct")+" / "+r.optInt("total")+" 題 · 未作答 "+r.optInt("unanswered")+" 題",15,Color.rgb(52,57,53),false);gap(c,12);label(c,"本次獲得 "+r.optInt("reward")+" 金幣",20,Color.rgb(24,31,33),true);label(c,"每題首次答對：1 顆星星＋3 枚金幣。",12,Color.rgb(52,57,53),false);button(content,"查看本次錯題",true,()->{bankMode="result";bankCity="全部地區";bankType=0;bankTopic="all";search="";bankPage=0;bank();});button(content,"再考一次",false,()->{if(lastFinished!=null){int nt=0;for(QuizCore.Question q:lastFinished.questions)if(q.tf)nt++;startSession(lastFinished.questions,true,QuizCore.timeLimitSeconds(false,nt,lastFinished.questions.size()-nt)/60,lastFinished.title,state.data.optString("city","基隆市"));}});button(content,"返回首頁",false,()->home());}
    private final List<QuizCore.Question> bankResults=new ArrayList<>();
    private Switch toggle(LinearLayout parent,String caption,boolean checked,java.util.function.Consumer<Boolean> change){Switch s=new Switch(this);s.setText(caption);s.setTextColor(ink);s.setTextSize(15);s.setPadding(0,dp(10),0,dp(10));s.setChecked(checked);parent.addView(s,new LinearLayout.LayoutParams(-1,dp(48)));s.setOnCheckedChangeListener((v,b)->change.accept(b));return s;}
    private void bank(){
        String title=bankMode.equals("wrong")?"錯題複習":bankMode.equals("result")?"本次錯題":"查看題庫";
        screen("bank",title,"依縣市與主題閱讀，展開答案即可查看答題解析。" );
        if(!bankMode.equals("all"))button(content,"返回全部題庫",false,()->{bankMode="all";bankCity="基隆市";bankType=1;bankTopic="all";bankPage=0;bank();});
        List<String> cityNames=new ArrayList<>();cityNames.add("全部地區");cityNames.add("交通法規");cityNames.addAll(Arrays.asList(ExamProfiles.REGIONS));String[] cities=cityNames.toArray(new String[0]);
        Spinner city=spinner(content,cities,cityNames.indexOf(bankCity));city.setContentDescription("題庫縣市");Spinner type=spinner(content,new String[]{"全部題型","是非題","選擇題"},bankType);type.setContentDescription("題型");
        String[] sorts=bankType==1?new String[]{"題號排序","答案是排序","答案否排序"}:new String[]{"題號排序","答案 1 排序","答案 2 排序","答案 3 排序","答案 4 排序"};if(bankSort>=sorts.length)bankSort=0;Spinner sort=spinner(content,sorts,bankSort);
        EditText query=new EditText(this);query.setSingleLine(true);query.setTextSize(16);query.setTextColor(ink);query.setHintTextColor(muted);query.setHint("搜尋題目或選項");query.setPadding(dp(12),dp(10),dp(12),dp(10));query.setBackground(shape(surface,line));query.setText(search);content.addView(query,new LinearLayout.LayoutParams(-1,dp(52)));gap(content,12);
        toggle(content,"單純模式",simpleMode,b->{simpleMode=b;safely(()->{state.data.put("simpleMode",b);state.save();});filterBank();});
        toggle(content,"全部顯示答案",showAnswers,b->{showAnswers=b;filterBank();});
        toggle(content,"顯示答題解析",showExplanations,b->{showExplanations=b;safely(()->{state.data.put("explanations",b);state.save();});filterBank();});
        JSONArray chapters=guide.chapters(bankCity);List<String> topicIds=new ArrayList<>(),topicLabels=new ArrayList<>();topicIds.add("all");topicLabels.add("全部主題");for(int i=0;i<chapters.length();i++){JSONObject c=chapters.optJSONObject(i);topicIds.add(c.optString("id"));topicLabels.add(c.optString("label"));}
        if(!topicIds.contains(bankTopic))bankTopic="all";
        if(chapters.length()>0){Spinner topic=spinner(content,topicLabels.toArray(new String[0]),topicIds.indexOf(bankTopic));topic.setContentDescription("記憶主題");topic.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){if(!bankTopic.equals(topicIds.get(i))){bankTopic=topicIds.get(i);bankPage=0;filterBank();}}});}
        if(guide.guides.has(bankCity))button(content,bankCity+"題解整理・最佳記憶法",false,()->memoryGuide(bankCity));
        LinearLayout jump=row(content);EditText number=new EditText(this);number.setHint("原題號");number.setContentDescription("原題號");number.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);number.setTextColor(ink);number.setTextSize(16);jump.addView(number,new LinearLayout.LayoutParams(0,dp(52),1));button(jump,"跳轉",false,()->{int n=parseNumber(number);for(QuizCore.Question q:bank.questions)if(q.city.equals(bankCity)&&q.number==n&&(bankType==0||q.tf==(bankType==1))){openQuestion(q);return;}throw new Exception("請選擇縣市及題型，並輸入題庫內的原題號。");});
        if(!search.isEmpty()||!bankTopic.equals("all"))button(content,"清除搜尋與主題篩選",false,()->{search="";bankTopic="all";bankPage=0;bank();});
        gap(content,12);questionCount=label(content,"",13,muted,false);gap(content,12);questionList=new LinearLayout(this);questionList.setOrientation(LinearLayout.VERTICAL);content.addView(questionList,new LinearLayout.LayoutParams(-1,-2));
        query.addTextChangedListener(new TextWatcher(){Runnable pending;public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){search=s.toString();bankPage=0;if(pending!=null)handler.removeCallbacks(pending);pending=()->{if(page.equals("bank"))filterBank();};handler.postDelayed(pending,250);}public void afterTextChanged(Editable e){}});
        city.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){if(!bankCity.equals(cities[i])){bankCity=cities[i];bankTopic="all";bankPage=0;bank();}}});
        type.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){if(bankType!=i){bankType=i;bankSort=0;bankPage=0;bank();}}});
        sort.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int i,long id){if(bankSort!=i){bankSort=i;bankPage=0;filterBank();}}});filterBank();
    }
    private void filterBank(){
        if(questionList==null||!page.equals("bank"))return;bankResults.clear();List<QuizCore.Question> source=bank.questions;
        if(bankMode.equals("result")&&lastFinished!=null){source=new ArrayList<>();for(int i=0;i<lastFinished.questions.size();i++)if(lastFinished.answers[i]!=lastFinished.questions.get(i).answer)source.add(lastFinished.questions.get(i));}
        for(QuizCore.Question q:source){if(!bankCity.equals("全部地區")&&!q.city.equals(bankCity))continue;if(bankType==1&&!q.tf||bankType==2&&q.tf)continue;if(!q.searchText().toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT)))continue;if(bankMode.equals("wrong")&&!state.wrong.contains(q.id))continue;if(!guide.inTopic(q,bankTopic))continue;bankResults.add(q);}
        bankResults.sort((a,b)->{if(bankSort>0){int selected=bankSort-1,ar=a.answer==selected?0:a.answer+1,br=b.answer==selected?0:b.answer+1;if(ar!=br)return ar-br;}int city=a.city.compareTo(b.city);if(!bankCity.equals("全部地區")||city==0){int t=Boolean.compare(!a.tf,!b.tf);return t!=0?t:Integer.compare(a.number,b.number);}return city;});
        int pages=Math.max(1,(bankResults.size()+29)/30);bankPage=Math.max(0,Math.min(bankPage,pages-1));questionCount.setText("共 "+bankResults.size()+" 題 · 第 "+(bankPage+1)+" / "+pages+" 頁 · 每頁 30 題");questionList.removeAllViews();
        if(bankResults.isEmpty()){label(card(questionList,surface),"沒有符合條件的題目，可以更換縣市或清除篩選。",17,ink,false);return;}
        for(int i=bankPage*30;i<Math.min(bankResults.size(),bankPage*30+30);i++)questionCard(bankResults.get(i));
        LinearLayout r=row(questionList);Button prev=button(r,"上一頁",false,()->{bankPage--;filterBank();scroll.smoothScrollTo(0,0);});prev.setEnabled(bankPage>0);Button next=button(r,"下一頁",true,()->{bankPage++;filterBank();scroll.smoothScrollTo(0,0);});next.setEnabled(bankPage+1<pages);
    }
    private void remember(QuizCore.Question q){safely(()->{state.data.put("lastRead",q.id);state.save();});}
    private void questionText(LinearLayout parent,QuizCore.Question q){label(parent,q.stem,state.data.optInt("font",21)-2,ink,true);for(int i=0;i<q.options.size();i++){gap(parent,4);label(parent,q.optionLabel(i),state.data.optInt("font",21)-3,muted,false);}}
    private void questionCard(QuizCore.Question q){
        LinearLayout c=card(questionList,surface);label(c,q.label()+(state.data.optString("lastRead").equals(q.id)?" · 目前閱讀位置":""),12,muted,false);gap(c,8);questionText(c,q);
        if(!simpleMode)safely(()->{JSONArray ids=guide.topics(q);List<String> topics=new ArrayList<>();for(int i=0;i<Math.min(2,ids.length());i++)topics.add(guide.chapter(q.city,ids.getString(i)).optString("label"));if(!topics.isEmpty()){gap(c,8);label(c,String.join(" / ",topics),12,muted,false);}});
        LinearLayout answer=new LinearLayout(this);answer.setOrientation(LinearLayout.VERTICAL);boolean[] expanded={showAnswers};Button show=button(c,showAnswers?"收起答案":"顯示答案",false,()->{});
        Runnable render=()->{answer.removeAllViews();show.setText(expanded[0]?"收起答案":"顯示答案");if(expanded[0]){gap(answer,12);label(answer,"答案："+q.answerLabel(),18,green,true);if(showExplanations)safely(()->explanationBox(answer,q));}};
        show.setOnClickListener(v->{expanded[0]=!expanded[0];if(expanded[0])remember(q);render.run();});if(simpleMode)c.setOnClickListener(v->{expanded[0]=!expanded[0];if(expanded[0])remember(q);render.run();});
        if(!simpleMode)button(c,"記住閱讀位置",false,()->{remember(q);toast("已記住這題的閱讀位置。");});c.addView(answer);render.run();
        if(bankMode.equals("wrong"))button(c,"已記住，移除錯題",false,()->{state.wrong.remove(q.id);state.save();filterBank();});
    }
    private QuizCore.Question fromReference(JSONObject reference){String id=reference.optString("id");for(QuizCore.Question q:bank.questions)if(q.webId().equals(id))return q;return null;}
    private void references(LinearLayout parent,JSONArray references,String prefix){if(references==null)return;for(int i=0;i<references.length();i++){JSONObject ref=references.optJSONObject(i);QuizCore.Question q=fromReference(ref);if(q!=null){Button b=button(parent,prefix+q.type()+"第 "+q.number+" 題",false,()->openQuestion(q));b.setTextSize(13);}}}
    private void explanationBox(LinearLayout parent,QuizCore.Question q)throws Exception{
        gap(parent,12);LinearLayout box=card(parent,surface);JSONObject e=guide.explanation(q);label(box,"答題解析",18,ink,true);gap(box,8);label(box,e.getString("takeaway"),16,ink,true);gap(box,8);label(box,e.getString("summary"),16,ink,false);references(box,e.optJSONArray("sources"),"題庫對照：");
        if(e.optBoolean("needsReview"))label(box,"題目或對照題已有變動，原補充解析待重新核對。",14,red,false);
        JSONArray groups=e.getJSONArray("comparisons");for(int i=0;i<groups.length();i++){JSONObject group=groups.getJSONObject(i);LinearLayout details=new LinearLayout(this);details.setOrientation(LinearLayout.VERTICAL);label(details,group.getString("prompt"),14,muted,false);JSONArray rows=group.getJSONArray("rows");for(int j=0;j<rows.length();j++){JSONObject r=rows.getJSONObject(j);gap(details,10);label(details,r.getString("label"),15,ink,true);label(details,r.getString("value"),15,ink,false);references(details,r.optJSONArray("sources"),"對照：");}button(box,group.getString("title"),false,()->details.setVisibility(details.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));box.addView(details);details.setVisibility(View.GONE);}
        gap(box,12);label(box,"自己回想："+e.getString("recallPrompt"),15,ink,true);if(!e.optBoolean("hasSpecificExplanation")&&!e.optBoolean("needsReview")){JSONArray tips=e.getJSONArray("memoryTips");for(int i=0;i<tips.length();i++){gap(box,6);label(box,"• "+tips.getString(i),14,muted,false);}}
        JSONArray related=e.getJSONArray("relatedQuestions");if(related.length()>0){LinearLayout relatedPanel=new LinearLayout(this);relatedPanel.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<related.length();i++){JSONObject ref=related.getJSONObject(i);QuizCore.Question other=fromReference(ref);if(other!=null)button(relatedPanel,other.type()+"第 "+other.number+" 題："+other.stem,false,()->openQuestion(other));}button(box,"相近題目一起看（"+related.length()+"）",false,()->relatedPanel.setVisibility(relatedPanel.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));box.addView(relatedPanel);relatedPanel.setVisibility(View.GONE);}
        gap(box,8);label(box,e.optBoolean("hasSpecificExplanation")?"依目前載入的題幹、選項與答案核對。":"依題庫答案與分類提供閱讀提示。",12,muted,false);
    }
    private void openQuestion(QuizCore.Question q)throws Exception{remember(q);ScrollView sc=new ScrollView(this);LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);p.setPadding(dp(18),dp(16),dp(18),dp(16));p.setBackgroundColor(bg);sc.addView(p);questionText(p,q);gap(p,12);label(p,"答案："+q.answerLabel(),18,green,true);if(showExplanations)explanationBox(p,q);new AlertDialog.Builder(this).setTitle(q.label()).setView(sc).setPositiveButton("返回閱讀",null).show();}
    private void tableRows(LinearLayout parent,JSONArray rows)throws JSONException{for(int n=0;n<rows.length();n++){JSONArray cells=rows.getJSONArray(n);LinearLayout c=card(parent,surface);for(int j=0;j<cells.length();j++)label(c,cells.getString(j),j==0?16:15,j==0?ink:muted,j==0);}}
