        JSONArray chapters=profile.getJSONArray("chapters");int count=0;for(QuizCore.Question q:bank.questions)if(q.city.equals(region))count++;label(content,"目前題庫 "+count+" 題 · 同一題可以屬於多個主題。",13,muted,false);gap(content,10);
